        "status": {
          "type": "string",
          "pattern": "^fail$",
          "description": "the status for a failure handling"
        },
        "data": {
          "description": "provides the wrapper for the details of why the request failed.",
          "$ref": "#/definitions/data-fail"
        }
      }
    },
    "error": {
